// Lookup from a hop name as a brewery publishes it to a canonical variety.
//
//   import { loadHopLookup, resolveHop } from './lib/hop-aliases.mjs';
//   const lookup = loadHopLookup();
//   resolveHop('Citra LupuLN2', lookup);   // { status: 'mapped', slug: 'citra', canonical: 'Citra', form: 'LupuLN2' }
//   resolveHop('Noble hops', lookup);      // { status: 'unmapped', reason: '...' }
//   resolveHop('Zzz', lookup);             // { status: 'unknown' }
//
// The data lives in two files, so a session that adds a name edits data, not code:
//   data/reference/hop-aliases.csv    generated by scripts/build-hop-data.mjs from the catalogue (canonical names,
//                                     aliases, experimental codes) plus product forms (kind "form")
//   data/reference/hop-unmapped.csv   hand maintained: names that are deliberately not a single variety, each with a reason

import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { REFERENCE } from './paths.mjs';
import { readCsvRecords } from './csv.mjs';

// Fold case, diacritics, trademark marks, apostrophes and punctuation: "Hallertau Mittelfrüh" and
// "hallertau mittelfruh" are the same key, and "Falconer's Flight" matches "Falconers Flight".
export function normalizeHopName(name) {
  return String(name)
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[®™℠©]/g, '')
    .replace(/['’`]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

export function hopSlug(canonical) {
  return normalizeHopName(canonical).replace(/ /g, '-');
}

// Product forms a brewer appends to a variety name. The form is reported separately from the variety.
export const HOP_FORMS = [
  { form: 'Cryo', variants: ['Cryo', 'Cryo Hops'] },
  { form: 'LupuLN2', variants: ['LupuLN2', 'Lupu LN2'] },
  { form: 'LUPOMAX', variants: ['LUPOMAX', 'Lupo Max'] },
  { form: 'Incognito', variants: ['Incognito'] },
  { form: 'HyperBoost', variants: ['HyperBoost', 'Hyper Boost'] },
  { form: 'DynaBoost', variants: ['DynaBoost', 'Dyna Boost'] },
  { form: 'Spectrum', variants: ['Spectrum'] },
  { form: 'T90', variants: ['T90', 'T 90', 'T90 pellets', 'pellets', 'pellet'] },
];

export function loadHopLookup(dir = REFERENCE) {
  const aliasFile = resolve(dir, 'hop-aliases.csv');
  const unmappedFile = resolve(dir, 'hop-unmapped.csv');
  const aliases = new Map();
  const forms = new Map();
  for (const row of readCsvRecords(readFileSync(aliasFile, 'utf8'))) {
    const key = normalizeHopName(row.alias);
    if (row.kind === 'form') forms.set(key, row.canonical);
    else aliases.set(key, { slug: row.slug, canonical: row.canonical });
  }
  const unmapped = new Map();
  if (existsSync(unmappedFile)) for (const row of readCsvRecords(readFileSync(unmappedFile, 'utf8'))) unmapped.set(normalizeHopName(row.name), row.reason);
  return { aliases, forms, unmapped };
}

export function resolveHop(name, lookup) {
  const key = normalizeHopName(name);
  const direct = lookup.aliases.get(key);
  if (direct) return { status: 'mapped', slug: direct.slug, canonical: direct.canonical, form: '' };
  const tokens = key.split(' ');
  const found = [];
  while (tokens.length > 1) {
    let matched = false;
    for (const size of [2, 1]) {
      if (tokens.length <= size) continue;
      const tail = tokens.slice(-size).join(' ');
      if (lookup.forms.has(tail)) {
        found.unshift(lookup.forms.get(tail));
        tokens.length -= size;
        matched = true;
        break;
      }
    }
    if (!matched) break;
  }
  if (found.length) {
    const base = lookup.aliases.get(tokens.join(' '));
    if (base) return { status: 'mapped', slug: base.slug, canonical: base.canonical, form: found.join(' ') };
  }
  const reason = lookup.unmapped.get(key);
  if (reason !== undefined) return { status: 'unmapped', reason };
  return { status: 'unknown' };
}
